"use client";

import { motion, type Transition, useReducedMotion } from "motion/react";
import { useId, useState } from "react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { BlockFrame } from "../parts/block-frame";
import { RollingText } from "../parts/rolling-text";
import { LoaderIcon } from "./icons";
import { type ClinicSetup, START, STEPS, type StepErrors, stepErrors } from "./multi-step-form/data";
import { ReviewList } from "./multi-step-form/review-list";
import { StepFields } from "./multi-step-form/step-fields";
import { Stepper } from "./multi-step-form/stepper";
import { SignedIn } from "./login/signed-in";
import { StepStage } from "./shared/step-stage";
import { useTimers } from "./shared/use-timers";

const WIDTH: Transition = { type: "spring", stiffness: 500, damping: 40 };

/**
 * Sets up a new clinic one decision at a time: name and kind, opening hours,
 * rooms and team, then a review. Enter submits the step through the native
 * form; a step with a problem says so beside the field and stays put.
 */
export function MultiStepForm({ className }: { className?: string }) {
  const titleId = useId();
  const reduce = useReducedMotion();
  const { later, clear } = useTimers();
  const [form, setForm] = useState<ClinicSetup>(START);
  const [step, setStep] = useState(0);
  const [reached, setReached] = useState(0);
  const [direction, setDirection] = useState(1);
  const [errors, setErrors] = useState<StepErrors>({});
  const [busy, setBusy] = useState(false);
  const [created, setCreated] = useState(false);
  const last = STEPS.length - 1;
  const current = STEPS[step]!;

  const goTo = (next: number) => {
    setDirection(next >= step ? 1 : -1);
    setStep(next);
    setReached((value) => Math.max(value, next));
    setErrors({});
  };

  const update = (patch: Partial<ClinicSetup>) => {
    setForm((value) => ({ ...value, ...patch }));
    setErrors({});
  };

  const submit = () => {
    const found = stepErrors(step, form);
    if (Object.keys(found).length > 0) {
      setErrors(found);
      return;
    }
    if (step < last) {
      goTo(step + 1);
      return;
    }
    setBusy(true);
    later(() => {
      setBusy(false);
      setCreated(true);
    }, 1000);
  };

  const label = busy ? "Creating the clinic" : step === last ? `Create ${form.name.trim() || "clinic"}` : "Continue";

  return (
    <BlockFrame aria-labelledby={titleId} className={cn("mx-auto max-w-2xl", className)}>
      <header className="flex flex-col gap-4 border-b border-border px-5 py-4">
        <div className="flex flex-wrap items-baseline justify-between gap-2">
          <h2 id={titleId} className="text-base font-semibold">
            Set up your clinic
          </h2>
          <p className="text-sm text-muted-foreground">
            Step <RollingText text={String(step + 1)} /> of {STEPS.length}
          </p>
        </div>
        {created ? null : <Stepper step={step} reached={reached} onPick={goTo} />}
      </header>

      <div className="p-5">
        <StepStage stepKey={created ? "created" : String(step)} direction={direction}>
          {created ? (
            <SignedIn
              via=""
              title={`${form.name.trim()} is ready`}
              line={`${form.rooms} rooms and ${form.practitioners} practitioners are set up. Next, invite your team.`}
              onSignOut={() => {
                clear();
                setForm(START);
                setCreated(false);
                setReached(0);
                goTo(0);
              }}
            />
          ) : (
            <form
              noValidate
              className="flex flex-col gap-5"
              onSubmit={(event) => {
                event.preventDefault();
                submit();
              }}
            >
              <div className="flex flex-col gap-1">
                <h3 className="text-lg font-semibold">{current.title}</h3>
                <p className="text-sm text-muted-foreground">{current.line}</p>
              </div>
              {step === last ? <ReviewList form={form} onEdit={goTo} /> : <StepFields step={step} form={form} errors={errors} update={update} />}
              <div className="flex items-center justify-between gap-3 border-t border-border pt-4">
                <Button type="button" variant="outline" disabled={step === 0 || busy} onClick={() => goTo(step - 1)}>
                  Back
                </Button>
                <Button asChild disabled={busy}>
                  <motion.button type="submit" layout={!reduce} transition={WIDTH} disabled={busy}>
                    <motion.span layout={reduce ? false : "position"} transition={WIDTH} className="flex items-center gap-2">
                      {busy ? <LoaderIcon aria-hidden="true" className="size-4 motion-safe:animate-spin" /> : null}
                      {label}
                    </motion.span>
                  </motion.button>
                </Button>
              </div>
            </form>
          )}
        </StepStage>
      </div>
    </BlockFrame>
  );
}

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

import { NumberTicker } from "@/components/motion/number-ticker";
import { cn } from "@/lib/utils";

/** Props for a formatted figure whose digits roll. */
export interface RollingTextProps {
  /** A figure that is already formatted, such as "$3,577" or "8.2 min". */
  text: string;
  className?: string;
}

/**
 * Shows a formatted figure and rolls each digit to its new value when the
 * text changes, as a counter does. Signs, separators and units stay still.
 * Each glyph is keyed by its place from the right, so a digit keeps its
 * column when the figure grows. It is for text that already has another
 * spoken source: the rolling columns are hidden from screen readers.
 */
export function RollingText({ text, className }: RollingTextProps) {
  const glyphs = [...text];
  return (
    <span className={cn("inline-flex tabular-nums", className)}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" className="inline-flex">
        {glyphs.map((glyph, index) => {
          const place = glyphs.length - 1 - index;
          return glyph >= "0" && glyph <= "9" ? (
            <NumberTicker key={place} value={Number(glyph)} />
          ) : (
            <span key={place} className="whitespace-pre">
              {glyph}
            </span>
          );
        })}
      </span>
    </span>
  );
}

