/** Everything the setup form collects. */
export interface ClinicSetup {
  name: string;
  kind: string;
  days: string[];
  opens: string;
  closes: string;
  rooms: number;
  practitioners: number;
  visitLength: string;
}

/** The answers a new form starts with. */
export const START: ClinicSetup = {
  name: "",
  kind: "physio",
  days: ["Mon", "Tue", "Wed", "Thu", "Fri"],
  opens: "08:00",
  closes: "18:00",
  rooms: 3,
  practitioners: 4,
  visitLength: "30",
};

/** The four steps, each with its title and helper line. */
export const STEPS = [
  { title: "Your clinic", line: "Patients see this name on the booking page and in reminders." },
  { title: "Opening hours", line: "Bookings can only land inside these hours. Each person can narrow them later." },
  { title: "Rooms and team", line: "Rough numbers are fine. You can add names and rooms after setup." },
  { title: "Check and create", line: "Read it over once. Every answer can be changed from Settings." },
] as const;

/** The kinds of practice a clinic can pick. */
export const KINDS = [
  { value: "physio", label: "Physiotherapy" },
  { value: "dental", label: "Dental" },
  { value: "gp", label: "General practice" },
  { value: "other", label: "Something else" },
];

/** The days of the week, in order. */
export const DAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];

/** Half-hour times from 06:00 to 22:00. */
export const TIMES = Array.from({ length: 33 }, (_, index) => {
  const minutes = 360 + index * 30;
  return `${String(Math.floor(minutes / 60)).padStart(2, "0")}:${minutes % 60 === 0 ? "00" : "30"}`;
});

/** The usual visit lengths, in minutes. */
export const VISIT_LENGTHS = ["15", "20", "30", "45", "60"];

/** The problems with one step's answers, by field. An empty object means the step can go on. */
export function stepErrors(step: number, form: ClinicSetup) {
  const errors: StepErrors = {};
  if (step === 0 && !form.name.trim()) errors.name = "Enter the clinic name.";
  if (step === 1 && form.days.length === 0) errors.days = "Pick at least one day.";
  if (step === 1 && form.closes <= form.opens) errors.hours = "Closing time must be after opening time.";
  return errors;
}

/** The problems `stepErrors` can find, each as the line shown beside its field. */
export interface StepErrors {
  name?: string;
  days?: string;
  hours?: string;
}

"use client";

import { Button } from "@/components/ui/button";

import { type ClinicSetup, KINDS } from "./data";

/** Props for the review list. `onEdit` opens the step that owns a row. */
export interface ReviewListProps {
  form: ClinicSetup;
  onEdit: (step: number) => void;
}

/** The last step: every answer on one row, each with a link back to its step. */
export function ReviewList({ form, onEdit }: ReviewListProps) {
  const rows: { label: string; value: string; step: number }[] = [
    { label: "Clinic", value: form.name.trim(), step: 0 },
    { label: "Practice", value: KINDS.find((kind) => kind.value === form.kind)?.label ?? "", step: 0 },
    { label: "Open on", value: form.days.join(", "), step: 1 },
    { label: "Hours", value: `${form.opens} to ${form.closes}`, step: 1 },
    { label: "Rooms and team", value: `${form.rooms} rooms, ${form.practitioners} practitioners`, step: 2 },
    { label: "Visits", value: `${form.visitLength} minutes`, step: 2 },
  ];

  return (
    <dl className="flex flex-col rounded-lg border border-border py-1">
      {rows.map((row) => (
        <div key={row.label} className="flex items-center gap-3 px-3 py-2 text-sm">
          <dt className="w-28 shrink-0 text-muted-foreground">{row.label}</dt>
          <dd className="min-w-0 flex-1 truncate">{row.value}</dd>
          <dd>
            <Button type="button" variant="link" size="sm" aria-label={`Change ${row.label.toLowerCase()}`} onClick={() => onEdit(row.step)}>
              Change
            </Button>
          </dd>
        </div>
      ))}
    </dl>
  );
}

"use client";

import { useId } from "react";

import { NumberField } from "@/components/motion/number-field";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";

import { type ClinicSetup, DAYS, KINDS, type StepErrors, TIMES, VISIT_LENGTHS } from "./data";
import { PickOne } from "./pick-one";

/** Props for the fields of one step. */
export interface StepFieldsProps {
  step: number;
  form: ClinicSetup;
  errors: StepErrors;
  update: (patch: Partial<ClinicSetup>) => void;
}

/** The fields of the first three steps of the clinic setup form. */
export function StepFields({ step, form, errors, update }: StepFieldsProps) {
  const nameId = useId();
  const kindId = useId();
  const daysId = useId();

  if (step === 0) {
    return (
      <div className="flex flex-col gap-4">
        <div className="flex flex-col gap-1.5">
          <label htmlFor={nameId} className="text-sm font-medium">
            Clinic name
          </label>
          <Input
            id={nameId}
            autoFocus
            placeholder="Harbour Street Physio"
            value={form.name}
            onChange={(event) => update({ name: event.target.value })}
            aria-invalid={errors.name ? true : undefined}
            aria-describedby={`${nameId}-error`}
          />
          <p id={`${nameId}-error`} className="min-h-5 text-sm text-destructive">
            {errors.name}
          </p>
        </div>
        <fieldset className="flex flex-col gap-2">
          <legend id={kindId} className="pb-2 text-sm font-medium">
            Kind of practice
          </legend>
          <RadioGroup aria-labelledby={kindId} value={form.kind} onValueChange={(kind) => update({ kind })} className="grid @md:grid-cols-2">
            {KINDS.map((kind) => (
              <label key={kind.value} className="flex cursor-pointer items-center gap-3 rounded-lg border border-border px-3 py-2.5 text-sm has-data-[state=checked]:border-primary">
                <RadioGroupItem value={kind.value} />
                {kind.label}
              </label>
            ))}
          </RadioGroup>
        </fieldset>
      </div>
    );
  }

  if (step === 1) {
    return (
      <div className="flex flex-col gap-4">
        <fieldset aria-describedby={`${daysId}-error`}>
          <legend className="pb-2 text-sm font-medium">Open on</legend>
          <div className="flex flex-wrap gap-2">
            {DAYS.map((day) => {
              const checked = form.days.includes(day);
              return (
                <label key={day} className="flex cursor-pointer items-center gap-2 rounded-lg border border-border px-2.5 py-1.5 text-sm has-data-[state=checked]:border-primary">
                  <Checkbox
                    checked={checked}
                    onCheckedChange={(value) =>
                      update({ days: value === true ? DAYS.filter((item) => item === day || form.days.includes(item)) : form.days.filter((item) => item !== day) })
                    }
                  />
                  {day}
                </label>
              );
            })}
          </div>
          <p id={`${daysId}-error`} className="min-h-5 pt-1 text-sm text-destructive">
            {errors.days}
          </p>
        </fieldset>
        <div className="grid grid-cols-2 gap-3">
          <PickOne label="Opens at" value={form.opens} options={TIMES} onChange={(opens) => update({ opens })} />
          <PickOne label="Closes at" value={form.closes} options={TIMES} onChange={(closes) => update({ closes })} />
        </div>
        <p role="alert" className="min-h-5 text-sm text-destructive">
          {errors.hours}
        </p>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-4">
      <div className="grid gap-4 @md:grid-cols-2">
        <NumberField label="Treatment rooms" value={form.rooms} onValueChange={(rooms) => update({ rooms })} min={1} max={40} />
        <NumberField label="Practitioners" value={form.practitioners} onValueChange={(practitioners) => update({ practitioners })} min={1} max={80} />
      </div>
      <PickOne label="Usual visit length" value={form.visitLength} options={VISIT_LENGTHS} suffix=" minutes" onChange={(visitLength) => update({ visitLength })} />
    </div>
  );
}

"use client";

import { useId } from "react";

import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";

/** A labelled select of times or lengths. */
export function PickOne({ label, value, options, onChange, suffix = "" }: { label: string; value: string; options: string[]; onChange: (value: string) => void; suffix?: string }) {
  const id = useId();
  return (
    <div className="flex flex-col gap-1.5">
      <label id={id} className="text-sm font-medium">
        {label}
      </label>
      <Select value={value} onValueChange={onChange}>
        <SelectTrigger aria-labelledby={id} className="w-full">
          <SelectValue />
        </SelectTrigger>
        <SelectContent>
          {options.map((option) => (
            <SelectItem key={option} value={option}>
              {option}
              {suffix}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    </div>
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { STEPS } from "./data";

/** Props for the stepper. `reached` is the furthest step opened so far. */
export interface StepperProps {
  step: number;
  reached: number;
  onPick: (step: number) => void;
}

/**
 * Numbered markers for the four steps. A finished step draws a check and can
 * be opened again; steps not reached yet stay locked.
 */
export function Stepper({ step, reached, onPick }: StepperProps) {
  const reduce = useReducedMotion();

  return (
    <ol className="flex items-center gap-2">
      {STEPS.map((item, index) => {
        const done = index < step || (index < reached && index !== step);
        const current = index === step;
        return (
          <li key={item.title} className="flex flex-1 items-center gap-2 last:flex-none">
            <Button
              type="button"
              variant="ghost"
              size="sm"
              disabled={index > reached}
              aria-current={current ? "step" : undefined}
              aria-label={`Step ${index + 1}, ${item.title}${done ? ", done" : ""}`}
              onClick={() => onPick(index)}
            >
              <span
                aria-hidden="true"
                className={cn(
                  "flex size-6 items-center justify-center rounded-full border text-xs font-semibold motion-safe:transition-colors",
                  current && "border-primary bg-primary text-primary-foreground",
                  done && !current && "border-chart-2 bg-chart-2 text-primary-foreground",
                  !current && !done && "border-border text-muted-foreground",
                )}
              >
                {done && !current ? (
                  <svg viewBox="0 0 16 16" className="size-3.5">
                    <motion.path
                      d="M3.5 8.5l3 3 6-7"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="2"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      initial={{ pathLength: reduce ? 1 : 0 }}
                      animate={{ pathLength: 1 }}
                      transition={{ duration: 0.3, ease: "easeOut" }}
                    />
                  </svg>
                ) : (
                  index + 1
                )}
              </span>
              <span className="hidden text-sm @xl:inline">{item.title}</span>
            </Button>
            {index < STEPS.length - 1 ? (
              <span aria-hidden="true" className="relative h-0.5 flex-1 overflow-hidden rounded-full bg-border">
                <span className={cn("absolute inset-0 origin-left bg-chart-2 motion-safe:transition-transform motion-safe:duration-300", index < reached ? "scale-x-100" : "scale-x-0")} />
              </span>
            ) : null}
          </li>
        );
      })}
    </ol>
  );
}

