"use client";

import { AnimatePresence, motion, type Transition, useReducedMotion } from "motion/react";
import { type ReactNode, useLayoutEffect, useRef, useState } from "react";

import { cn } from "@/lib/utils";

const SHELL: Transition = { type: "spring", stiffness: 420, damping: 40 };
const SLIDE: Transition = { type: "spring", stiffness: 520, damping: 46 };
const FADE: Transition = { duration: 0.15 };

/** Props for a stage that swaps one step for the next. */
export interface StepStageProps {
  /** Changes when the step changes, so the old step leaves and the new one enters. */
  stepKey: string;
  /** 1 when moving forward, -1 when moving back. The new step slides in from that side. */
  direction: number;
  children: ReactNode;
  className?: string;
}

/**
 * Shows one step at a time. The new step slides a short way in from the
 * direction of travel while the shell springs to its height. Under reduced
 * motion the steps fade and the height changes at once.
 */
export function StepStage({ stepKey, direction, children, className }: StepStageProps) {
  const reduce = useReducedMotion();
  const inner = useRef<HTMLDivElement>(null);
  const [height, setHeight] = useState<number | "auto">("auto");

  useLayoutEffect(() => {
    const element = inner.current;
    if (!element) return;
    const observer = new ResizeObserver(() => setHeight(element.offsetHeight));
    observer.observe(element);
    return () => observer.disconnect();
  }, []);

  const offset = reduce ? 0 : direction * 24;

  return (
    <motion.div
      animate={{ height }}
      initial={false}
      transition={reduce ? { duration: 0 } : SHELL}
      className={cn("relative -mx-1 overflow-hidden", className)}
    >
      <div ref={inner} className="p-1">
        <AnimatePresence mode="popLayout" initial={false}>
          <motion.div
            key={stepKey}
            initial={{ opacity: 0, x: offset }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -offset }}
            transition={reduce ? FADE : SLIDE}
          >
            {children}
          </motion.div>
        </AnimatePresence>
      </div>
    </motion.div>
  );
}

"use client";

import { useCallback, useEffect, useRef } from "react";

/**
 * Schedules the simulated waits a demo needs, such as a server reply. Every
 * pending timer is cleared when the block unmounts or `clear` runs.
 */
export function useTimers() {
  const pending = useRef(new Set<ReturnType<typeof setTimeout>>());

  const clear = useCallback(() => {
    for (const timer of pending.current) clearTimeout(timer);
    pending.current.clear();
  }, []);

  const later = useCallback((run: () => void, ms: number) => {
    const timer = setTimeout(() => {
      pending.current.delete(timer);
      run();
    }, ms);
    pending.current.add(timer);
    return timer;
  }, []);

  useEffect(() => clear, [clear]);

  return { later, clear };
}
